import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { TanStackRouterVite } from '@tanstack/router-vite-plugin';

export default defineConfig({
  server: {
    port: 6382,
    host: true,
  },
  plugins: [
    TanStackRouterVite({
      routesDirectory: './src/routes',
      generatedRouteTree: './src/routeTree.gen.ts',
    }),
    react(),
  ],
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import { RouterProvider, createRouter, createRootRoute, createRoute, Outlet } from '@tanstack/react-router';
import { AuthProvider, useAuth } from './auth';
import { homeRoute } from './routes/home';
import { loginRoute } from './routes/login';
import { dashboardRoute } from './routes/dashboard';

const rootRoute = createRootRoute({
  component: () => (
    <AuthProvider>
      <Outlet />
    </AuthProvider>
  ),
});

const routeTree = rootRoute.addChildren([
  homeRoute,
  loginRoute,
  dashboardRoute,
]);

const router = createRouter({
  routeTree,
  context: {
    auth: undefined as any,
  },
  defaultPreload: 'intent',
});

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}

function App() {
  const auth = useAuth();
  return <RouterProvider router={router} context={{ auth }} />;
}

const rootEl = document.getElementById('root')!;
ReactDOM.createRoot(rootEl).render(
  <React.StrictMode>
    <AuthProvider>
      <InnerApp />
    </AuthProvider>
  </React.StrictMode>,
);

function InnerApp() {
  const auth = useAuth();
  return <RouterProvider router={router} context={{ auth }} />;
}

import React, { createContext, useContext, useState, useMemo } from 'react';

export interface AuthContextValue {
  isAuthenticated: boolean;
  login: () => void;
  logout: () => void;
}

export interface AuthRouterContext {
  auth: AuthContextValue;
}

export const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);

  const value = useMemo<AuthContextValue>(
    () => ({
      isAuthenticated,
      login: () => setIsAuthenticated(true),
      logout: () => setIsAuthenticated(false),
    }),
    [isAuthenticated],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return ctx;
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  server: {
    port: 6382,
    host: true,
  },
  plugins: [react()],
});

import * as React from 'react';
import { createRoute } from '@tanstack/react-router';
import { rootRoute } from './root';

function HomeComponent() {
  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Home Page</h1>
      <p>This is the public home page.</p>
      <a
        href="/dashboard"
        onClick={(e) => {
          e.preventDefault();
          window.history.pushState({}, '', '/dashboard');
          window.dispatchEvent(new PopStateEvent('popstate'));
        }}
      >
        Go to Dashboard
      </a>
    </div>
  );
}

export const homeRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: HomeComponent,
});

import * as React from 'react';
import { createRoute, Link } from '@tanstack/react-router';
import { rootRoute } from './root';

function HomeComponent() {
  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Home Page</h1>
      <p>This is the public home page.</p>
      <Link to="/dashboard">Go to Dashboard</Link>
    </div>
  );
}

export const homeRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: HomeComponent,
});

import * as React from 'react';
import { createRoute, useNavigate } from '@tanstack/react-router';
import { rootRoute } from './root';
import { useAuth } from '../auth';

function LoginComponent() {
  const auth = useAuth();
  const navigate = useNavigate({ from: '/login' });

  const handleLogin = () => {
    auth.login();
    navigate({ to: '/dashboard' });
  };

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Login Page</h1>
      <p>Click the button below to log in.</p>
      <button onClick={handleLogin}>Login</button>
    </div>
  );
}

export const loginRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/login',
  component: LoginComponent,
});

import * as React from 'react';
import { createRoute, redirect, useNavigate } from '@tanstack/react-router';
import { rootRoute } from './root';
import { useAuth, type AuthRouterContext } from '../auth';

function DashboardComponent() {
  const auth = useAuth();
  const navigate = useNavigate({ from: '/dashboard' });

  const handleLogout = () => {
    auth.logout();
    navigate({ to: '/login' });
  };

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Welcome to Dashboard</h1>
      <p>This page is protected and only accessible to authenticated users.</p>
      <button onClick={handleLogout}>Logout</button>
    </div>
  );
}

export const dashboardRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/dashboard',
  beforeLoad: ({ context }) => {
    const authContext = context as AuthRouterContext | undefined;
    if (!authContext?.auth?.isAuthenticated) {
      throw redirect({ to: '/login' });
    }
  },
  component: DashboardComponent,
});

